entries[20162] = { ["name"] = "Siegel des Kreuzfahrers", ["text"] = "40 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit dem Geist eines Kreuzfahrers und verleiht 60 Nahkampfangriffskraft. Außerdem greift der Paladin um 40% schneller an, verursacht jedoch bei jedem Angriff weniger Schaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 10 Sek. lang und erhöht den erlittenen Heiligschaden bis zu 30. Eure Nahkampfangriffe frischen die Dauer dieses Siegels auf. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[20164] = { ["name"] = "Siegel der Gerechtigkeit", ["text"] = "13% von Grundmana\nSofort\nErfüllt den Paladin 30 Sek. lang mit dem Geist der Gerechtigkeit, der jedem Nahkampfangriff eine Chance verleiht, 2 Sek. lang zu betäuben. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 10 Sek. lang und hindert ihn an der Flucht. Eure Nahkampfangriffe frischen die Dauer dieses Siegels auf. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[20165] = { ["name"] = "Siegel des Lichts", ["text"] = "110 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit göttlichem Licht, das jedem Nahkampfangriff eine Chance verleiht, den Paladin um 39 Punkt(e) zu heilen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 10 Sek. lang und verleiht Nahkampfangriffen, die gegen den gerichteten Feind ausgeführt werden, eine Chance den Angreifer um 25 Punkt(e) zu heilen. Eure Nahkampfangriffe erneuern die Dauer dieses Effekts. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[20166] = { ["name"] = "Siegel der Weisheit", ["text"] = "135 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit göttlicher Weisheit, die jedem Nahkampfangriff eine Chance verleiht, 50 Punkt(e) Mana des Paladins wiederherzustellen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 10 Sek. lang und verleiht Angriffen und Zaubern, die gegen den gerichteten Feind ausgeführt werden, eine Chance beim Angreifer 33 Punkt(e) Mana wiederherzustellen. Eure Nahkampfangriffe erneuern die Dauer dieses Effekts. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
