entries[20287] = { ["name"] = "Siegel der Rechtschaffenheit", ["text"] = "40 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit heiligem Geist, der jedem Nahkampfangriff zusätzlichen Heiligschaden in Höhe von 4 - 13 verleiht. Langsamere Waffen verursachen mehr Heiligschaden pro Schlag. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind 36 bis 39 Heiligschaden zu." }
