entries[20347] = { ["name"] = "Siegel des Lichts", ["text"] = "140 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit göttlichem Licht, das jedem Nahkampfangriff eine Chance verleiht, den Paladin um 53 Punkt(e) zu heilen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 10 Sek. lang und verleiht Nahkampfangriffen, die gegen den gerichteten Feind ausgeführt werden, eine Chance den Angreifer um 34 Punkt(e) zu heilen. Eure Nahkampfangriffe erneuern die Dauer dieses Effekts. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[20348] = { ["name"] = "Siegel des Lichts", ["text"] = "180 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit göttlichem Licht, das jedem Nahkampfangriff eine Chance verleiht, den Paladin um 76 Punkt(e) zu heilen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 10 Sek. lang und verleiht Nahkampfangriffen, die gegen den gerichteten Feind ausgeführt werden, eine Chance den Angreifer um 49 Punkt(e) zu heilen. Eure Nahkampfangriffe erneuern die Dauer dieses Effekts. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
