entries[20699] = { ["name"] = "Wucherwurzeln", ["text"] = "30 Meter Reichweite\nSofort\nUmwickelt in der Nähe befindliche Feinde mit Wurzeln, macht sie bis zu 15 Sek. lang bewegungsunfähig und fügt ihnen alle 3 Sek. 333 bis 367 Punkt(e) Naturschaden zu." }
