entries[20705] = { ["name"] = "Machtschild 500", ["text"] = "Falls man im Gefecht Opfer eines kritischen Treffers wird, besteht eine Chance von 1%, in einen magischen Schild gehüllt zu werden, der die nächsten 515 Punkt(e) Schaden absorbiert.\n(Procchance: 5%)" }
entries[20706] = { ["name"] = "Machtwort: Schild 500", ["text"] = "40 Meter Reichweite\nSofort\nNutzt die Kraft der Seele zum Abschirmen und absorbiert dabei 515 Punkt(e) Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden." }
entries[20707] = { ["name"] = "Seelenstein-Auferstehung", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nSpeichert die Seele des befreundeten Ziels. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es sich mit 400 Gesundheit und 700 Mana wiederbeleben." }
