entries[20711] = { ["name"] = "Geist der Erlösung", ["text"] = "Beim Tod verwandelt sich der Priester 10 Sek. lang in einen Geist der Erlösung. Der Geist kann sich weder bewegen oder angreifen, noch kann er das Ziel von Zaubern oder Effekten sein. In dieser Gestalt kann der Priester jeglichen Heilzauber ohne irgendwelche Kosten wirken. Nach Ablauf der Verwandlung stirbt der Priester." }
