entries[20752] = { ["name"] = "Seelenstein herstellen (gering)", ["text"] = "85% von Grundmana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen geringen Seelenstein entstehen. Der Seelenstein kann zum Speichern der Seele eines Ziels benutzt werden. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 750 Gesundheit und 1200 Mana wiederbelebt werden.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
