entries[21084] = { ["name"] = "Siegel der Rechtschaffenheit", ["text"] = "20 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit heiligem Geist, der jedem Nahkampfangriff zusätzlichen Heiligschaden in Höhe von 3 - 9 verleiht. Langsamere Waffen verursachen mehr Heiligschaden pro Schlag. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind 26 Heiligschaden zu." }
